export type TranscriptSpeakerAssignment = { transcript_id: string; channel: number; speaker_index: number | null; speaker_label: string; anchor_word_id: string }

export type TranscriptSpeakerHint = { id?: string | null; word_id: string; type: string; value?: JsonValue }

export type TranscriptWithData = { id: string; user_id?: string; created_at?: string; session_id: string; started_at?: number; ended_at?: number | null; memo_md?: string; words?: TranscriptWord[]; speaker_hints?: TranscriptSpeakerHint[] }

export type TranscriptWord = { id?: string | null; text: string; start_ms: number; end_ms: number; channel: number; speaker?: string | null; metadata?: Partial<{ [key in string]: JsonValue }> | null }

export type TranscriptionAvailability = "disabled" | "loading" | "ready" | "in_use" | "unavailable" | "stopping"

export type TranscriptionFailure = "access_denied" | "source_unavailable" | "resource_limit" | "engine_unavailable" | "engine_failed" | "invalid_output" | "storage" | "interrupted"

export type TranscriptionJobPage = { jobs: TranscriptionJobSnapshot[]; next_cursor: string | null }

export type TranscriptionJobRequest = { session_id: string; expected_recording_sha256: string; expected_transcript: AbsentTranscriptExpectation; model: string; languages?: string[]; keywords?: string[] }

export type TranscriptionJobResult = { job_id: string; session_id: string; transcript: TranscriptWithData }

export type TranscriptionJobSnapshot = { id: string; session_id: string; state: TranscriptionJobState; phase: TranscriptionPhase | null; created_at: string; updated_at: string; result_available: boolean; failure: TranscriptionFailure | null; publication: TranscriptionPublication | null }

export type TranscriptionJobState = "queued" | "running" | "cancelling" | "cancelled" | "succeeded" | "failed" | "interrupted" | "conflict" | "empty" | "uncertain"

export type TranscriptionPhase = "preparing" | "transcribing" | "publishing"

export type TranscriptionPolicy = {
/**
 * Operator-facing public model alias, never a model file path.
 */
model: string | null;
/**
 * Advisory model state; operation admission remains authoritative.
 */
availability: TranscriptionAvailability; batch_enabled: boolean; live_enabled: boolean }

/**
 * A durable historical decision, not confirmation that these bytes are still current.
 */
export type TranscriptionPublication = { revision: string; transcript_id: string }

export type UpdateVaultRequest = { name: string; expected_revision: string }

export type UploadAttachmentRequest = { filename: string; size_bytes: number; sha256: string }

export type VaultInfo = { id: string; name: string; kind: VaultKind; role: VaultRole; revision: string }

export type VaultKind = "personal" | "shared"

export type VaultMutation = { vault_id: string; revision: string }

export type VaultRole = "reader" | "editor" | "owner"

/**
 * Whether a finalized word is stable or awaiting correction.
 *
 * A word is `Pending` when it has been confirmed by the STT model but a
 * correction source (cloud STT fallback, LLM postprocessor, etc.) is still
 * processing it. The word has an ID and is persisted, but its text may be
 * replaced when the correction resolves via `TranscriptDelta::replaced_ids`.
 */
export type WordState = "final" | "pending"
